import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>每次裁剪都有一个比例，不管你选没选它。比例就是保留下来的矩形形状，它决定了图片能放在哪、看起来怎么样。</p>\n<p>正方形裁剪和宽幅裁剪不能互换。一个适合头像，另一个适合横幅，用错了，平台会替你重新裁剪。</p>\n<p>这篇文章会讲清常见比例、各自的用途和选择方法。还包括自定义比例、背后的计算，以及忽视比例会带来的错误。选好比例后，用<a href=\"/zh/caijian-tupian/\">图片裁剪工具</a>按比例裁剪，就不用担心平台再替你乱裁了。</p>\n<h2 id=\"what-is-an-aspect-ratio\">什么是长宽比</h2>\n<p>长宽比是图片宽度与高度的关系，用两个数字加冒号表示，比如16:9。</p>\n<p>这两个数字是比例，不是像素数。16:9的图片可以是1920×1080像素，也可以是1280×720像素，形状是一样的。</p>\n<p>想知道任意图片的比例，用宽度除以高度。1200像素宽、800像素高的照片，比例是1.5，也就是3:2。</p>\n<p>比例之所以重要，是因为目的地对形状有要求。平台要正方形，就会裁掉宽照片；打印机要4:3，其他形状要么被拉伸、要么被修剪。</p>\n<h2 id=\"ratio-1-1\">1:1——正方形</h2>\n<p>1:1表示宽和高相等，图片是完美的正方形。这是社交媒体上最常见的比例，头像和网格帖子都用它。</p>\n<p>正方形给人平衡、中性的感觉。适合人像、产品照，以及任何需要放进网格、不偏向某个方向的内容。</p>\n<p>要注意，大多数平台会把正方形头像显示成圆形。正方形的四个角会被切掉，所以脸一定要放在框内足够靠里的位置。</p>\n<p>裁成1:1时，主体居中，头顶留一点空间。脸贴着上边缘，圆形裁剪会切掉头发；主体放在角落，可能会被完全切掉。</p>\n<h2 id=\"ratio-4-3\">4:3——经典照片形状</h2>\n<p>4:3比正方形略宽。曾经是电视屏幕和早期数码相机的标准形状，现在仍然适合传统照片。</p>\n<p>文件和扫描页面用它很好，内容比正方形宽，又没有视频画面那么宽。标准纸张尺寸打印也合适。</p>\n<p>很多手机相机仍然提供4:3模式。相机用这个比例拍摄，裁成4:3几乎不用去掉任何东西。</p>\n<p>主体需要一点横向空间、但画面又不该有全景感时，用4:3。合影、室内、文件都适合这个形状。</p>\n<h2 id=\"ratio-3-2\">3:2——相机标准</h2>\n<p>3:2来自35毫米胶片相机，至今仍是大多数单反和无反相机的默认形状。比4:3宽，比16:9窄。</p>\n<p>适合风景和街头摄影。多出来的宽度让场景有了呼吸空间，又不会把图片变成全景。</p>\n<p>打印尺寸常常与这个比例吻合。6×4英寸的照片正好是3:2，裁成这个形状打印，不用再修剪。</p>\n<p>相机拍3:2、又经常打印的话，裁剪也保持这个比例。喜欢的照片被打印店裁掉边缘的意外就能避免。</p>\n<h2 id=\"ratio-16-9\">16:9——宽屏</h2>\n<p>16:9是现代屏幕的形状：电视、显示器、横放的手机屏幕。宽阔、有电影感，天生适合横跨屏幕的内容。</p>\n<p>视频封面、网站横幅、演示文稿都该选它。16:9的裁剪能填满空间，两边不留空白条。</p>\n<p>代价是纵向空间。从竖构图照片裁16:9，上下要丢掉大量像素，主体必须能舒服地待在一个细条带里。</p>\n<p>16:9裁剪里的重要内容放在中间。平台经常为手机再次修剪左右两侧，靠近左右边缘的东西可能消失。</p>\n<h2 id=\"ratio-4-5-and-9-16\">4:5与9:16——竖版形状</h2>\n<p>竖版比例很重要，因为大多数人是竖着拿手机看内容的。4:5是竖版人像，比正方形在手机屏幕上占的地方更大。</p>\n<p>4:5适合社交动态里的竖版帖子。在手机上显示得比正方形帖子更大，更显眼，又不会占满整个屏幕。</p>\n<p>9:16是竖屏手机的全屏比例。短视频、竖屏故事和竖版视频都是这个形状，能从边缘到边缘填满屏幕。</p>\n<p>竖版裁剪对构图要求很高。宽幅风景挤进9:16，两侧大部分都会丢掉，这个比例适合单一主体，不适合开阔场景。</p>\n<h2 id=\"custom-ratios\">自定义比例：没有预设合适时</h2>\n<p>有时候没有标准比例能对上目的地。特定尺寸的横幅、书封面、固定像素尺寸的表单，都需要自定义形状。</p>\n<p>裁剪工具的自由模式可以把选框拖成任意形状。工具会显示精确的输出尺寸，可以按要求的尺寸精确匹配。</p>\n<p>自定义比例也适合从大图里截细节。一页里的一段文字、照片里的一个标志、人群里的一张脸，都需要预设给不了的形状。</p>\n<p>用自定义比例时，先把需要的像素尺寸写下来。凭眼睛裁很容易出错，对着数字裁才是精确的。</p>\n<h2 id=\"ratio-vs-resolution\">比例与分辨率：两回事</h2>\n<p>比例描述形状，分辨率描述像素大小。两张图可以形状相同、分辨率不同，也可以分辨率相同、形状不同。</p>\n<p>500×500像素的1:1裁剪和2000×2000像素的1:1裁剪，形状相同，但后者的像素是前者的16倍。</p>\n<p>这很重要，因为平台需要1000像素时，500像素的裁剪图拉伸后会变模糊——形状对了，分辨率错了。</p>\n<p>两个数字都要检查。裁剪工具会显示输出尺寸，下载前用比例确认形状、用像素数确认大小。</p>\n<h2 id=\"ratio-mistakes\">比例用错会出什么问题</h2>\n<p>最常见的错误是裁成一个比例、再拉伸去适配另一个形状。拉伸会让人脸和物体变形，损伤一眼就能看出来。</p>\n<p>另一个错误是让平台替你重新裁剪。正方形照片当横幅上传，平台会自己裁，裁掉什么由它决定，不是由你。</p>\n<p>很多人还会忘记，换比例会丢像素。宽照片裁成正方形，左右各三分之一都没了，主体可能就在被丢掉的部分里。</p>\n<p>解决办法是裁剪前先按目的地规则选好比例。花五秒钟查一下平台的尺寸指南，上面三个错误都能避免。</p>\n<h2 id=\"ratio-for-print\">打印用的比例</h2>\n<p>打印尺寸有自己的比例，不一定和屏幕形状一致。6×4英寸是3:2，10×8英寸是5:4，A4纸大约是1.41:1。</p>\n<p>打印前查一下纸张尺寸的比例，按比例裁。16:9的照片印在4:3的纸上，要么留白边，要么被打印机裁掉边缘。</p>\n<p>打印不只看形状，还要看分辨率。裁得很小的图印大了会发虚，比例和像素数都要确认。</p>\n<p>拿不准时，裁得比打印尺寸稍大一点，让打印店修剪多余部分。留一点余量，比裁得正好是错误形状要安全。</p>\n<h2 id=\"ratio-workflow\">选比例的工作流程</h2>\n<p>先列出图片要出现的所有地方。一张照片既要当头像、又要当横幅、还要打印，就需要从同一张原图裁出三个不同版本。</p>\n<p>每个版本单独从原文件裁。裁剪图再裁剪会损失画质，从原图重新裁则始终清晰。</p>\n<p>每个文件按目的地和比例命名，比如avatar-1x1.png或banner-16x9.png。清楚的名字能防止把错误的形状上传到错误的地方。</p>\n<p>留好原文件。目的地会改尺寸规则，留着原图才能按新比例重新裁，而不用从已经损坏的副本开始。</p>\n<h2 id=\"ratio-cheat-sheet\">比例速查表</h2>\n<p>头像、网格帖子、任何方形或圆形显示的内容，用1:1。主体居中，头顶留空间。</p>\n<p>传统照片、文件、标准纸张打印，用4:3。这是最稳妥的通用照片形状。</p>\n<p>相机照片要印6×4英寸时，用3:2。它符合胶片标准，也符合大多数单反的输出。</p>\n<p>横幅、封面、幻灯片，用16:9。重要内容放在中央，远离手机屏幕会修剪的边缘。</p>\n<h2 id=\"ratio-for-video-thumbnails\">视频封面的比例</h2>\n<p>视频封面几乎总是16:9，因为它们放在用宽屏形状的视频播放器上。裁成其他比例，平台会拉伸或加黑边。</p>\n<p>封面裁剪里脸和主体要大。封面在信息流里显示得很小，主体太小会看不见，主体够大才能吸引目光。</p>\n<p>打算在封面上加标题文字时留出空间。16:9裁剪里主体放一边、另一边留白，文字就有地方放。</p>\n<p>发布前在手机上检查封面。电脑上看着好的裁剪，在手机上可能看不清，那时封面只有几厘米宽。</p>\n<h2 id=\"ratio-for-ecommerce\">电商与商品列表的比例</h2>\n<p>商品列表通常要求正方形图片，因为方形网格排列整齐、看着专业。大多数店铺用1:1最稳妥。</p>\n<p>有些平台要求特定比例，比如4:3或3:2，不符合就会替你裁剪。上架前查好列表规则，不要事后补救。</p>\n<p>商品网格里一致性比创意更重要。每件商品用同样的比例、同样的边距裁剪，目录看着整齐、可信。</p>\n<p>产品页面的主图用宽一点的比例更好，比如16:9或3:2。它能在场景中展示产品，周围还有生活化背景的空间。</p>\n<h2 id=\"ratio-and-composition\">比例与构图：形状如何改变感觉</h2>\n<p>正方形给人平静、平衡的感觉，因为没有哪个方向占主导。适合人像、静物和任何应该居中稳定的内容。</p>\n<p>宽比例给人开阔、有电影感的感觉，因为视线会横穿画面。适合风景、城市和任何以宽度为重点的场景。</p>\n<p>竖比例给人亲密、专注的感觉，因为视线在窄框里上下移动。适合单一主体，比如一个人、一栋楼、一棵树。</p>\n<p>选比例时也要考虑感觉，不只是目的地。风景裁成正方形会失去空间感，人像裁成宽幅会失去亲近感。</p>\n<h2 id=\"ratio-changes-over-time\">比例会变：跟上平台的步伐</h2>\n<p>平台的尺寸规则经常变。去年合适的比例，今年可能已经放不进去了。信息流曾经要正方形，现在可能更喜欢竖版人像；横幅位置也可能有了新尺寸。</p>\n<p>每张重要照片都留好原文件。平台改规则时，可以用原图按新比例重新裁，而不是拉伸旧的裁剪图。</p>\n<p>为某个平台裁剪前，先查它的尺寸指南。两分钟的检查，能防止平台替你把图裁坏。</p>\n<p>列一张自己最常用的比例清单，平台一改就更新。桌上贴一张纸条，写着头像1:1、横幅16:9、故事9:16，每次裁剪都能省时间。</p>\n<p>竖版帖子想在手机信息流里脱颖而出，用4:5；全屏故事和竖版视频用9:16。实际操作步骤见<a href=\"/zh/blog/ruhe-caijian-tupian/\">如何裁剪图片</a>，完整概览见<a href=\"/zh/blog/tupian-caijian-wanquan-zhinan/\">图片裁剪完全指南</a>。照片还需要改尺寸的话，用<a href=\"/zh/tiaozheng-tupian-chicun/\">图片尺寸调整工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"裁剪里的1:1是什么意思？","answer":"宽和高相等，裁出来是完美的正方形。1:1适合头像和网格帖子。主体居中、头顶留空间，因为很多平台会把正方形显示成圆形，四个角会被切掉。"},{"question":"YouTube视频封面该用什么比例？","answer":"用16:9标准宽屏形状，对应1280×720像素的封面尺寸。主体和文字放在中央，小屏幕上边缘可能会被修剪。"},{"question":"能把照片裁成相机没拍过的比例吗？","answer":"能。裁成新比例只是从边缘去掉像素，直到形状吻合。宽照片可以变正方形，正方形也可以变宽横幅，只要保留下来的区域对目的地来说够大。"},{"question":"打印照片该用什么比例？","answer":"按纸张尺寸匹配：6×4英寸用3:2，10×8英寸用5:4，A4大约用1.41:1。比例和像素数都要检查，裁得很小的图印大了会发虚。"},{"question":"为什么Instagram上传后会重新裁剪我的照片？","answer":"上传的图片不符合它为该位置设定的比例时，Instagram会重新裁剪。上传前按正确比例裁剪，比如网格帖子用1:1、竖版帖子用4:5，构图就掌握在自己手里。"},{"question":"长宽比和分辨率有什么区别？","answer":"长宽比是图片的形状，比如16:9；分辨率是像素大小，比如1920×1080。两张图片可以形状相同、分辨率不同。上传或打印前，两个都要检查。"}];
